"""Match a whole path against a glob pattern. See TASK.md for the rules.

The pattern is first compiled into a token list (raising ValueError for
malformed patterns), then matched against the path with a forward
set-of-states simulation, so no recursion depth grows with the path length.
"""

_LIT = "lit"        # literal character (also used for escaped characters)
_SEP = "sep"        # unescaped '/' separating segments
_ANY = "any"        # '?': one character that is not '/'
_STAR = "star"      # '*': zero or more characters that are not '/'
_CLASS = "class"    # '[...]' / '[!...]': one character, never '/'
_DSEG = "dseg"      # whole-segment '**' followed by '/': zero or more whole segments, with their '/'
_DEND = "dend"      # whole-segment '**' at the end of the pattern: matches any remainder


def _parse_class(pat, i):
    """Parse a bracket class starting at pat[i] == '['. Return (token, next_index)."""
    n = len(pat)
    j = i + 1
    negated = False
    if j < n and pat[j] == "!":
        negated = True
        j += 1
    ranges = []
    first = True
    while True:
        if j >= n:
            raise ValueError("unclosed '[' in pattern")
        c = pat[j]
        if c == "]" and not first:
            j += 1
            break
        first = False
        if j + 2 < n and pat[j + 1] == "-" and pat[j + 2] != "]":
            lo, hi = c, pat[j + 2]
            if hi < lo:
                raise ValueError("reversed range %r-%r in pattern" % (lo, hi))
            ranges.append((lo, hi))
            j += 3
        else:
            ranges.append((c, c))
            j += 1
    return (_CLASS, negated, ranges), j


def _tokenize(pat):
    tokens = []
    n = len(pat)
    i = 0
    seg_start = True  # True at the start of the pattern and just after an unescaped '/'
    while i < n:
        c = pat[i]
        if c == "\\":
            if i + 1 >= n:
                raise ValueError("pattern ends with a backslash")
            tokens.append((_LIT, pat[i + 1]))
            i += 2
            seg_start = False
        elif c == "/":
            tokens.append((_SEP,))
            i += 1
            seg_start = True
        elif c == "*":
            if seg_start and pat[i:i + 2] == "**" and (i + 2 == n or pat[i + 2] == "/"):
                if i + 2 == n:
                    tokens.append((_DEND,))
                    i += 2
                    seg_start = False
                else:
                    # '**/' as a unit: the '/' is absorbed into the token.
                    tokens.append((_DSEG,))
                    i += 3
                    seg_start = True
            else:
                tokens.append((_STAR,))
                i += 1
                seg_start = False
        elif c == "?":
            tokens.append((_ANY,))
            i += 1
            seg_start = False
        elif c == "[":
            tok, i = _parse_class(pat, i)
            tokens.append(tok)
            seg_start = False
        else:
            tokens.append((_LIT, c))
            i += 1
            seg_start = False
    return tokens


def _class_contains(tok, ch):
    _, negated, ranges = tok
    inside = any(lo <= ch <= hi for lo, hi in ranges)
    return inside != negated


def matches(pattern, path):
    """True when the whole path matches the glob pattern. See TASK.md."""
    tokens = _tokenize(pattern)
    T = len(tokens)
    n = len(path)
    # reach[p] holds the token indices ti such that tokens[:ti] matches path[:p].
    reach = [set() for _ in range(n + 1)]
    reach[0].add(0)
    for p in range(n + 1):
        cur = reach[p]
        for ti in range(T + 1):
            if ti not in cur:
                continue
            if ti == T:
                if p == n:
                    return True
                continue
            tok = tokens[ti]
            kind = tok[0]
            if kind == _DEND:
                return True  # matches zero or more whole segments: any remainder
            if kind == _DSEG:
                cur.add(ti + 1)  # zero segments
                # one or more whole segments: consume any non-empty prefix ending in '/'
                for j in range(p + 1, n + 1):
                    if path[j - 1] == "/":
                        reach[j].add(ti + 1)
                continue
            if kind == _STAR:
                cur.add(ti + 1)  # zero characters
                if p < n and path[p] != "/":
                    reach[p + 1].add(ti)  # one more character, stay in the star
                continue
            if p >= n:
                continue
            ch = path[p]
            if kind == _LIT or kind == _SEP:
                want = tok[1] if kind == _LIT else "/"
                if ch == want:
                    reach[p + 1].add(ti + 1)
            elif kind == _ANY:
                if ch != "/":
                    reach[p + 1].add(ti + 1)
            elif kind == _CLASS:
                if ch != "/" and _class_contains(tok, ch):
                    reach[p + 1].add(ti + 1)
    return T in reach[n]
